"""Contract test — blacklist_reconciliation.json isolation discipline.

Background
----------
``audit_dashboard/data/blacklist_reconciliation.json`` is a VERDICT
sidecar generated by ``tools/blacklist_reconciler.py``. It carries the
cross-check of quality_gates BLOCKED_SOURCE_SYSTEMS vs dashboard_data.json
systems (RESURRECTION_CANDIDATE / KILL_CONFIRMED / MUTATE_FIRST / NO_LIVE_DATA
verdicts per strategy). It currently carries::

    "_schema_note": "Generated by tools/blacklist_reconciler.py; ..."
    "blacklist_only": True

The payload encodes VERDICT data — never a sizing signal. The schema
contract is the ``blacklist_only: True`` gate flag.

See:
- ``audit_dashboard/data/blacklist_reconciliation.json`` for the payload
- ``tools/blacklist_reconciler.py`` for the writer
"""

from __future__ import annotations

import json
import os
import re
from pathlib import Path

import pytest

REPO = Path(__file__).resolve().parent.parent

SCAN_ROOTS = [
    REPO / "tools",
    REPO / "audit_trail",
    REPO / "alpha_engine",
]

EXEMPT_BASENAMES = {
    "blacklist_reconciler.py",                   # writer
    "test_no_blacklist_reconciliation_consumer.py",  # self
}

EXEMPT_SUFFIX_PARTS = ("__pycache__", ".pyc")

SIDECAR_FILENAME = "blacklist_reconciliation.json"
GUARD_FLAG = "blacklist_only"
ALLOW_COMMENT_RE = re.compile(
    r"#\s*allowed:\s*blacklist[_-]reconciliation\s+consumer\b"
)
SIDECAR_CONTRACT_KEYS_REQUIRED = ("_schema_note", "blacklist_only")

CRON_MODE = os.environ.get("BLACKLIST_RECONCILIATION_CRON_MODE", "") == "1"


def _consumes_sidecar(content: str) -> bool:
    if SIDECAR_FILENAME not in content:
        return False
    intent_patterns = (
        "open(", "read_text", "read_bytes",
        "json.load", "json.loads",
        "yaml.safe_load", "yaml.load",
        "tomllib.load",
        ".load(", ".loads(",
    )
    return any(pat in content for pat in intent_patterns)


def _carries_guard(content: str) -> bool:
    return GUARD_FLAG in content


def _carries_allow_marker(content: str) -> bool:
    return bool(ALLOW_COMMENT_RE.search(content))


def _is_exempt(path: Path) -> bool:
    if path.name in EXEMPT_BASENAMES:
        return True
    if any(part in EXEMPT_SUFFIX_PARTS for part in path.parts):
        return True
    return False


def _scan_files():
    for root in SCAN_ROOTS:
        if not root.exists():
            continue
        for path in root.rglob("*.py"):
            if not path.is_file():
                continue
            if _is_exempt(path):
                continue
            yield path


def test_no_unguarded_consumer_in_scan_roots():
    violations: list[str] = []
    for path in _scan_files():
        try:
            content = path.read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError):
            continue
        if not _consumes_sidecar(content):
            continue
        if _carries_allow_marker(content):
            continue
        if _carries_guard(content):
            continue
        violations.append(path.relative_to(REPO).as_posix())

    assert not violations, (
        "Unguarded consumers of blacklist_reconciliation.json detected. "
        "Every *.py that opens the sidecar must EITHER reference "
        "`blacklist_only` OR carry a line reading exactly "
        "`# allowed: blacklist-reconciliation consumer` (or underscore "
        "variant `blacklist_reconciliation`). "
        f"Violations: {violations}"
    )


def test_sidecar_payload_carries_required_contract_keys():
    sidecar_path = REPO / "audit_dashboard" / "data" / SIDECAR_FILENAME

    if not sidecar_path.exists():
        if CRON_MODE:
            pytest.fail(
                f"HARD REGRESSION: {sidecar_path.relative_to(REPO).as_posix()} "
                "is missing AFTER the blacklist reconciler step ran "
                "(BLACKLIST_RECONCILIATION_CRON_MODE=1). Investigate the writer "
                "(tools/blacklist_reconciler.py) before re-running."
            )
        pytest.skip(
            f"{sidecar_path.relative_to(REPO).as_posix()} not yet produced; "
            "the blacklist-reconciler cron step will land it."
        )

    payload = json.loads(sidecar_path.read_text(encoding="utf-8"))

    missing = [k for k in SIDECAR_CONTRACT_KEYS_REQUIRED if k not in payload]
    assert not missing, (
        f"{sidecar_path.relative_to(REPO).as_posix()} is missing required "
        f"contract keys: {missing}."
    )

    assert payload["blacklist_only"] is True, (
        "blacklist_only must be a strict boolean True; got "
        f"{payload['blacklist_only']!r} instead."
    )


def test_exempt_set_includes_writer_and_self():
    today = REPO / "tests" / "test_no_blacklist_reconciliation_consumer.py"
    writer = REPO / "tools" / "blacklist_reconciler.py"
    assert today.name in EXEMPT_BASENAMES
    assert writer.name in EXEMPT_BASENAMES, (
        "EXEMPT_BASENAMES must contain "
        f"{writer.name!r} (the blacklist reconciliation payload's writer)."
    )
